Item.method_code:
	BusinessLogic businessLogic = new BusinessLogic(this, RequestState);
	businessLogic.Run();

	return this;
}

private sealed class BusinessLogic
{
	private readonly Item contextItem;
	private readonly Aras.Server.Core.IContextState requestState;

	public BusinessLogic(Item contextItem, Aras.Server.Core.IContextState requestState)
	{
		this.contextItem = contextItem;
		this.requestState = requestState;
	}

	public void Run()
	{
		string select = contextItem.getAttribute("select");
		if (!string.IsNullOrEmpty(select) && select.Contains("expiration_status", StringComparison.InvariantCultureIgnoreCase))
		{
			requestState.Add("expiration_status_requested", true);
			if (!select.Contains("start_date", StringComparison.InvariantCultureIgnoreCase))
			{
				contextItem.setAttribute("select", $"{select},start_date");
			}

			if (!select.Contains("orderBy", StringComparison.InvariantCultureIgnoreCase))
			{
				contextItem.setAttribute("orderBy", "expiration_date desc, feature");
			}
		}
	}
